    }

    String method2(String str,char c){
      if (str == null) {
        return null;
      }
      int len=str.length();
      int st=0;
      while ((st < len) && (str.charAt(st) == c)) {
        st++;
      }
      while ((len > st) && (str.charAt(len - 1) == c)) {
        len--;
      }
      return ((st > 0) || (len < str.length())) ? str.substring(st,len) : str;
